// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {GameItems, Neuron} from "../src/GameItems.sol";

contract InvMutTest is Test {
    GameItems c;

    function setUp() public { c = new GameItems(address(this), address(this)); }

    function testFuzz_property(uint256 dailyAllowance, uint256 quantity, address actor) public {
        vm.assume(actor != address(0) && actor != address(c));
        uint256 da = bound(dailyAllowance, 1, 65535);
        uint256 q = bound(quantity, 1, da);

        // buyer actor is funded via the contributor mint
        Neuron n = new Neuron(address(this), address(this), actor);
        c.instantiateNeuronContract(address(n));
        // C must hold SPENDER_ROLE so approveSpender inside mint succeeds
        n.addSpender(address(c));

        // admin (this contract) creates an item: infinite supply, transferable,
        // zero price (no payment needed), dailyAllowance = da
        c.createGameItem("item", "", false, true, 0, 0, uint16(da));

        vm.prank(actor);
        c.mint(0, q);

        // Rule: after a purchase of q, the remaining daily allowance is da - q.
        assertTrue(c.getAllowanceRemaining(actor, 0) == da - q);
    }
}
